import{_ as d,C as s,o as i,c as l,E as n,a3 as c,w as h,j as t,a}from"./chunks/framework.D8n1j12q.js";const p="/versions/cli/v1.3.44/screens/devices/euclid.png",g="/versions/cli/v1.3.44/screens/devices/euclid-hold.png",u="/versions/cli/v1.3.44/screens/devices/euclid-layer.png",k=JSON.parse('{"title":"Euclid","description":"","frontmatter":{"title":"Euclid","pageClass":"device-doc"},"headers":[],"relativePath":"devices/euclid.md","filePath":"devices/euclid.md"}'),m={name:"devices/euclid.md"};function v(y,e,b,f,E,_){const r=s("DeviceHeading"),o=s("ManualRelated");return i(),l("div",null,[n(r,{slug:"euclid",title:"Euclid"}),e[1]||(e[1]=c('<p>Euclidean rhythm generator</p><p><img src="'+p+'" alt="Euclid: 4 hits in 16 steps, 4 in 12 and 5 in 16; L4 is off." class="screen"></p><h2 id="when-to-use-it" tabindex="-1">When to use it <a class="header-anchor" href="#when-to-use-it" aria-label="Permalink to &quot;When to use it&quot;">​</a></h2><p>Make drum patterns from steps and hits. Give each of the four layers its own length for shifting polyrhythms.</p><p>A new Euclid plays only <strong>L1</strong>: 4 hits in 16 steps on C3.</p><p>Every layer follows the song: step 1 lands on Start, and a pattern one bar long starts again on every bar. Two layers with the same <strong>RATE</strong> and <strong>STEPS</strong> always play the same step.</p><div class="info custom-block"><p class="custom-block-title">INFO</p><p>Put a <a href="/versions/cli/v1.3.44/devices/clock">Clock</a> before it in the rack. Without one it doesn&#39;t play.</p></div><h2 id="editing-layers" tabindex="-1">Editing layers <a class="header-anchor" href="#editing-layers" aria-label="Permalink to &quot;Editing layers&quot;">​</a></h2><p>Euclid opens on the <strong>GRID</strong> tab: four layers, <strong>L1</strong> to <strong>L4</strong>. <strong>Select + Back</strong> switches to the pencil tab, which holds <strong>BYPASS</strong>.</p><table tabindex="0"><thead><tr><th>Control</th><th>On a layer</th></tr></thead><tbody><tr><td>Hold <strong>Select</strong> and turn</td><td>Changes the layer&#39;s note</td></tr><tr><td>Hold <strong>Select</strong> without turning</td><td>Opens the <strong>LAYER</strong> panel</td></tr></tbody></table><p><img src="'+g+'" alt="Euclid: hold Select and turn to change the note" class="screen"></p><h3 id="layer-panel" tabindex="-1">LAYER panel <a class="header-anchor" href="#layer-panel" aria-label="Permalink to &quot;LAYER panel&quot;">​</a></h3><p>Each layer has its own settings, and each one can have its own <strong>MODULATION</strong> and <strong>MAPPING</strong>. Rows edit like any value: see <a href="./../navigation/controls#edit-a-value">Edit a value</a>. <strong>Back</strong> closes the panel.</p><p><img src="'+u+'" alt="LAYER 1: 4 hits in 16 steps at 1/16." class="screen"></p><h2 id="settings" tabindex="-1">Settings <a class="header-anchor" href="#settings" aria-label="Permalink to &quot;Settings&quot;">​</a></h2><div class="device-params-table"><table tabindex="0"><thead><tr><th>Parameter</th><th>Range</th><th>What it does</th></tr></thead><tbody><tr><td>BYPASS</td><td>OFF / ON</td><td>ON: MIDI passes through and the layers keep their place in silence. OFF: they come back in time. See <a href="/versions/cli/v1.3.44/devices/#bypass">BYPASS</a>.</td></tr></tbody></table></div><h2 id="layer-parameters" tabindex="-1">Layer parameters <a class="header-anchor" href="#layer-parameters" aria-label="Permalink to &quot;Layer parameters&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Range</th><th>What it does</th></tr></thead><tbody><tr><td>ENABLED</td><td>OFF / ON</td><td>ON: the layer plays. Turned back on, it comes back in time.</td></tr><tr><td>STEPS</td><td>1 – 16</td><td>Number of steps.</td></tr><tr><td>PULSES</td><td>1 – 16</td><td>Number of hits spread over the steps. At most <strong>STEPS</strong>.</td></tr><tr><td>RATE</td><td>1/1 – 1/64</td><td>Length of each step.</td></tr><tr><td>SHIFT</td><td>0 – 15</td><td>Moves the hits along the steps.</td></tr><tr><td>NOTE</td><td>C-2 – G8</td><td>Note of the hits.</td></tr><tr><td>CHANNEL</td><td>1 – 16</td><td>MIDI channel of the layer.</td></tr><tr><td>VELOCITY</td><td>1 – 127</td><td>Velocity of the hits.</td></tr><tr><td>GATE</td><td>0% – 200%</td><td>Note length as a share of the step.</td></tr></tbody></table>',18)),n(o,null,{default:h(()=>[...e[0]||(e[0]=[t("ul",null,[t("li",null,[t("a",{href:"/versions/cli/v1.3.44/racks/"},"Racks"),a(" — build a chain of devices")]),t("li",null,[t("a",{href:"/versions/cli/v1.3.44/concepts/mapping"},"Mapping"),a(" — put a device setting on a knob or an LFO")]),t("li",null,[t("a",{href:"/versions/cli/v1.3.44/concepts/modulation"},"Modulation"),a(" — move a setting while you play")])],-1)])]),_:1})])}const N=d(m,[["render",v]]);export{k as __pageData,N as default};
